//! What each tool TAKES: one struct per tool, its `inputSchema` generated by `schemars` and the call
//! read by its `Deserialize`, so the schema and the handler cannot disagree about an argument.
//!
//! The doc comment of a field is that argument's `description`, and a client reads it. Each `///`
//! line break is a space on the wire, so wrap at a space. A field with no doc comment has no
//! `description`; an `Option` is an optional argument unless it is `#[schemars(required)]`, anything
//! else a required one, in the order declared here.
//!
//! ⚠ **[`parse_args`] is the one parse of a call, and every refusal stays the tool's own words.** They
//! are pinned word for word by the goldens (`crates/vike-mcp/tests/fixtures/mcp_wire/`), and serde's
//! (`invalid type: …`, `missing field …`) are not them, so:
//! - a value of the wrong type is refused through the caller's `refuse(argument, value)`, the text the
//!   tool has always given for it;
//! - a REQUIRED argument is an `Option` marked `#[schemars(required)]`: the schema requires it, serde
//!   never refuses its absence, and the handler does, in its own words and its own order;
//! - an argument a tool has always read as ABSENT when it is not of its type (`rank_by`, the gate's
//!   three) is `#[serde(default, deserialize_with = "lenient")]`, and still reads so.
//!
//! The handler then runs the checks it always ran, on the struct.
//!
//! ⚠ **`Deserialize` is also where the declared order lives.** A JSON map sorts its keys
//! (`serde_json/preserve_order` flips every map in the build, the root `Cargo.toml` says so beside
//! `schemars`), and `skills/` lists arguments in declared order.
//! `crates/vike-mcp/src/tool_schemas.rs`'s `declared_fields` reads the order out of the derive.

use schemars::{JsonSchema, Schema, SchemaGenerator, json_schema};
use serde::Deserialize;
use serde::de::{DeserializeOwned, Deserializer, Error as _};
use serde_json::{Map, Value, json};

/// The ONE parse of a tool call: `args` read into `T`. A value `T` cannot take is refused with
/// `refuse(argument, value)`, the tool's own words; with several, the first in the call's key order.
/// `args` that are no object read as no arguments, as every `Value::get` read them.
pub(super) fn parse_args<T: DeserializeOwned>(
    args: &Value,
    refuse: impl Fn(&str, &Value) -> String,
) -> Result<T, String> {
    let Value::Object(given) = args else {
        return parse_args(&json!({}), refuse);
    };
    serde_json::from_value(args.clone()).map_err(|whole| {
        // Every field is optional to serde (the module doc), so the one that refuses alone is it.
        let alone = |(name, value): (&String, &Value)| {
            let one = Map::from_iter([(name.clone(), value.clone())]);
            serde_json::from_value::<T>(Value::Object(one)).is_err()
        };
        given
            .iter()
            .find(|&arg| alone(arg))
            .map_or_else(|| whole.to_string(), |(k, v)| refuse(k, v))
    })
}

/// An argument read as ABSENT when it is not of its type, as the tool has always read it.
fn lenient<'de, D: Deserializer<'de>, T: DeserializeOwned>(
    deserializer: D,
) -> Result<Option<T>, D::Error> {
    Ok(Option::<T>::deserialize(Value::deserialize(deserializer)?).ok().flatten())
}

/// A search argument the wire carries as a TOKEN: a JSON number rendered, a string as given, anything
/// else refused. `Value::as_str` alone was the trap: `"trials": 128`, the number the schema asks for,
/// vanished in silence.
fn search_token<'de, D: Deserializer<'de>>(deserializer: D) -> Result<Option<String>, D::Error> {
    match Value::deserialize(deserializer)? {
        Value::Null => Ok(None),
        Value::Number(n) => Ok(Some(n.to_string())),
        Value::String(s) => Ok(Some(s)),
        _ => Err(D::Error::custom("neither a number nor its decimal string")),
    }
}

/// An argument as given, an explicit `null` too (`Some(Value::Null)`), for the one tool that refuses
/// a `null` apart from an absent argument.
fn as_given<'de, D: Deserializer<'de>>(deserializer: D) -> Result<Option<Value>, D::Error> {
    Value::deserialize(deserializer).map(Some)
}

/// The `inputSchema` of `T` as a client sees it: `type`, `properties`, and `required` when something
/// is. What `schemars` adds beside those (`$schema`, `title`, `format`, `minimum`,
/// `additionalProperties`, a `null` in an optional's `type`) is no part of what this surface
/// advertises, so it is kept out by naming what stays.
pub(super) fn input_schema<T: JsonSchema>() -> Value {
    trimmed(&schemars::schema_for!(T).to_value())
}

/// The `outputSchema` of a tool's answer struct `T`, trimmed as [`input_schema`] is, and read for what serde
/// WRITES (`for_serialize`, as rmcp's own `schema_for_output` reads it): a field is required unless it is
/// `skip_serializing_if`, so an answer's `Option` is left out when `None`, never a `null` the schema refuses.
pub(super) fn output_schema<T: JsonSchema>() -> Value {
    let generator = schemars::generate::SchemaSettings::draft2020_12().for_serialize();
    trimmed(&generator.into_generator().into_root_schema_for::<T>().to_value())
}

/// A generated schema with only what this surface advertises: `type`, `properties`, `required`.
fn trimmed(raw: &Value) -> Value {
    let properties: Map<String, Value> = raw["properties"]
        .as_object()
        .into_iter()
        .flatten()
        .map(|(name, property)| (name.clone(), advertised(property)))
        .collect();
    let mut schema = json!({ "type": "object", "properties": properties });
    if let Some(required) = raw.get("required") {
        schema["required"] = required.clone();
    }
    schema
}

/// One argument: its one `type`, its `enum`, its `description` on one line.
fn advertised(property: &Value) -> Value {
    let kind = match &property["type"] {
        Value::Array(types) => types.iter().find(|t| t.as_str() != Some("null")),
        // Any value (an answer's `serde_json::Value`): no `type`, where a `null` one would be no schema.
        Value::Null => None,
        kind => Some(kind),
    };
    let mut out = Map::new();
    if let Some(kind) = kind {
        out.insert("type".to_string(), kind.clone());
    }
    if let Some(values) = property.get("enum") {
        out.insert("enum".to_string(), values.clone());
    }
    if let Some(description) = property["description"].as_str() {
        out.insert("description".to_string(), json!(description.replace('\n', " ")));
    }
    Value::Object(out)
}

/// `run_sweep`'s `optimizer`: rendered from the protocol's own roster, never typed out. §15.1 of
/// `docs/superpowers/specs/2026-09-12-backtest-cli-surface-design.md` makes this the AGENT leg of the
/// one-roster gate: a model can only ask for a method the SCHEMA names, so a hand-typed list here would
/// leave every agent a grid user the day a fifth method shipped, which is exactly the state §12 says
/// this stage exists to end.
fn search_method_schema(_: &mut SchemaGenerator) -> Schema {
    let methods = vike_model::run_request::search_methods::SEARCH_METHODS;
    json_schema!({ "type": "string", "enum": methods })
}

/// The arguments every write tool takes, spliced into each one's schema (`tool_schemas.rs`'s `row`,
/// on `is_write_tool`), so their wording cannot drift between tools, which is how the old inline
/// copies ended up in four different spellings.
#[derive(Default, Deserialize, JsonSchema)]
pub(super) struct WriteGate {
    /// optional rationale — WHY this command is being issued. Recorded in the node's audit trail
    /// (control characters stripped, capped at 512 chars); never reaches the order, the core, or the
    /// venue.
    #[serde(default, deserialize_with = "lenient")]
    pub(super) reason: Option<String>,
    /// must be true AND accompanied by a valid `preview_token` to execute; either one missing returns
    /// a preview instead
    #[serde(default, deserialize_with = "lenient")]
    pub(super) confirm: Option<bool>,
    /// the `preview_token` returned by this tool's preview call. Fires ONCE, expires after 60s, and is
    /// BOUND to the exact command it previewed — confirming a different command with it is refused.
    #[serde(default, deserialize_with = "lenient")]
    pub(super) preview_token: Option<String>,
}

impl WriteGate {
    /// The gate's arguments of a write call, read apart from its command (`crate::tool_verbs`'s
    /// `verb_from_tool_args`), so no gate argument can alter the command that gets built. Each reads
    /// as absent when it is not of its type, so this refuses nothing.
    pub(super) fn of(args: &Value) -> WriteGate {
        parse_args(args, |_, _| String::new()).unwrap_or_default()
    }

    /// The OPTIONAL operator/agent RATIONALE, trimmed, a blank one `None`. It rides BESIDE the command
    /// on the wire (`Request::Command { cmd, reason }`), never inside it. The node sanitizes it again
    /// before recording it (`vike_tradehub::audit::sanitize_reason` is the authority); this is only the
    /// client-side normalization.
    pub(super) fn reason(&self) -> Option<String> {
        self.reason.as_deref().map(str::trim).filter(|s| !s.is_empty()).map(str::to_string)
    }

    /// Whether the call confirms, and the token it confirms with: `None` unless BOTH arrived.
    pub(super) fn confirmed_token(&self) -> Option<&str> {
        self.preview_token.as_deref().filter(|_| self.confirm == Some(true))
    }
}

