#[derive(Deserialize, JsonSchema)]
pub(super) struct SubmitOrderArgs {
    #[schemars(required)]
    pub(super) venue: Option<String>,
    #[schemars(required)]
    pub(super) symbol: Option<String>,
    /// 1 buy / -1 sell
    #[schemars(required)]
    pub(super) side: Option<i64>,
    #[schemars(required)]
    pub(super) qty: Option<f64>,
    /// market | limit | stop | stop_limit | take_profit | market_to_limit | trailing | trailing_limit |
    /// pegged | trailing_take_profit (default market); stop, stop_limit and take_profit fire at
    /// trigger_price; trailing and trailing_limit trail the market by `trail` (or `trail_percent`) and
    /// take no price, their trigger_price an optional activation; trailing_take_profit is trailing's
    /// if-touched twin, a sell's trigger sits `trail` (or `trail_percent`) above the lowest price since it
    /// rests and fires when the price rises to it, a buy's the mirror, with no price and no
    /// trigger_price; pegged takes `peg` and no price or trigger_price
    pub(super) order_type: Option<String>,
    pub(super) price: Option<f64>,
    pub(super) trigger_price: Option<f64>,
    pub(super) reduce_only: Option<bool>,
    /// optional, trailing, trailing_limit and trailing_take_profit only (it or trail_percent required
    /// there): the trail, the distance in price (never a percent) the stop keeps from the best price
    /// since it activated. A modify changes a trailing order's size only
    pub(super) trail: Option<f64>,
    /// optional, the three trailing kinds only, in place of trail: the trail as a percent of the best
    /// price since it activated, above 0 and below 100; a venue that trails by price only refuses it by
    /// name
    pub(super) trail_percent: Option<f64>,
    /// optional, trailing_limit (and required there) and trailing_take_profit only: the limit offset in
    /// price, zero or more; its limit is the stop less it for a sell, plus it for a buy (a
    /// trailing_take_profit with none fires as a market order)
    pub(super) limit_offset: Option<f64>,
    /// optional, pegged only (and required there): the anchor the venue keeps the order at, best (its
    /// own side of the touch) | mid | market (the far side) | primary (its own side of the national
    /// best bid and offer); a venue that holds no pegged order refuses it by name
    pub(super) peg: Option<String>,
    /// optional, with peg only: the distance in price from the anchor, positive aggressive (a buy pays
    /// more), negative passive; default 0
    pub(super) peg_offset: Option<f64>,
    /// optional, a stop or stop_limit only: once the price reaches this level, on the protected side of
    /// the stop (a sell stop's above it, a buy stop's below), the order becomes what adjust_to names,
    /// once; a venue that cannot adjust a stop refuses it by name
    pub(super) adjust_at: Option<f64>,
    /// with adjust_at (and required there): what the order becomes, stop | stop_limit | trailing
    pub(super) adjust_to: Option<String>,
    /// with adjust_at (and required there): the stop price of what it becomes, on the near side of
    /// adjust_at (a sell's below it, a buy's above)
    pub(super) adjust_stop: Option<f64>,
    /// with adjust_to stop_limit only (and required there): its limit price
    pub(super) adjust_limit: Option<f64>,
    /// with adjust_to trailing only (it or adjust_trail_percent required there): its trail in price
    pub(super) adjust_trail: Option<f64>,
    /// with adjust_to trailing only, in place of adjust_trail: its trail as a percent, above 0 and below
    /// 100
    pub(super) adjust_trail_percent: Option<f64>,
    /// WHICH ACCOUNT of `venue` — node_snapshot's venues[].account, exactly. Omit it only where the
    /// node has ONE account of the venue, running or not: anywhere else an unnamed command is REFUSED, with nothing
    /// sent, and the refusal lists the books (a lane twin is that one account's second lane). DEFAULT
    /// names the unlabelled one deliberately. The preview_token is bound to it
    pub(super) account: Option<String>,
    /// optional: this order's id. Omitted, the server mints one and the preview shows it. A resend
    /// under an id the node already holds is refused; a resend under a minted id is a new order
    pub(super) order_client_id: Option<String>,
    /// optional: the quantity the venue SHOWS of a limit order (an iceberg's visible slice, or 0 for a
    /// hidden order), below qty; a slice the venue cannot show is EMULATED by the node (plain limits
    /// of that size, one at a time), and a hidden order it cannot hide is refused by name
    pub(super) display_qty: Option<f64>,
    /// optional, a limit order only: fill all of it in one execution or none of it; it rests until it
    /// can (all-or-none at once is time_in_force fok); a venue that cannot refuses the order by name
    pub(super) all_or_none: Option<bool>,
    /// optional, a limit order only: take every venue's liquidity at once up to the limit; not with
    /// post_only; a venue that cannot refuses the order by name
    pub(super) sweep_to_fill: Option<bool>,
    /// optional, a limit order only: the market sees the limit price, and the order executes up to the
    /// price plus this for a buy, less this for a sell; above zero; a venue that cannot refuses the
    /// order by name
    pub(super) discretionary_amount: Option<f64>,
    /// optional: hold the order on the node and send it at this moment, epoch milliseconds UTC, in
    /// the future. node_snapshot lists it in held_exits with its release until then, and
    /// cancel_order cancels it there
    pub(super) release_at: Option<i64>,
    /// optional, with release_at: hold it also until the price is there, above:<price> or
    /// below:<price>; above:<SYMBOL>:<price> reads another symbol the account's engine trades
    pub(super) release_when_price: Option<String>,
    /// optional, with a release_when_price that names its symbol: the venue whose price it reads, a
    /// venue id (binance, bybit, ...) and a price source only, never traded; an account of that venue on
    /// the node must trade the symbol. node_snapshot's held_exits row names it as release_venue, and
    /// says in waiting why an order whose moment came is still held
    pub(super) release_when_price_on: Option<String>,
    /// optional: the order's lifetime, gtc (the default) | day | ioc | fok | gtd (with gtd_expiry) |
    /// post_only on a limit order, or an auction on a market or limit order, at_open | at_close
    /// (at_open on a market_to_limit too: the opening auction); a venue that cannot do it refuses the
    /// order by name
    pub(super) time_in_force: Option<String>,
    /// optional, with time_in_force gtd only: when the order ends, epoch milliseconds UTC, in the
    /// future
    pub(super) gtd_expiry: Option<i64>,
}

#[derive(Deserialize, JsonSchema)]
pub(super) struct SubmitOrderListArgs {
    #[schemars(required)]
    pub(super) venue: Option<String>,
    #[schemars(required)]
    pub(super) symbol: Option<String>,
    /// as submit_order's account: every leg goes to this one account
    pub(super) account: Option<String>,
    /// 1 buy / -1 sell: the entry's side (an oco's two legs both take it)
    #[schemars(required)]
    pub(super) side: Option<i64>,
    /// the size of every leg but a ladder's targets (an oco's two legs, an oto's entry and exit, a ladder's entry
    /// and its stop)
    #[schemars(required)]
    pub(super) qty: Option<f64>,
    /// oco | oto | ladder. oco: a limit at limit_price and a stop at stop_price (a stop-limit at stop_limit_price)
    /// or a trailing stop by trail, the first to fill cancels the other. oto: an entry (a limit at entry_price, else
    /// market) and ONE reduce-only exit on the other side held until it fills, a stop at stop_price, a limit at
    /// limit_price or a trailing stop by trail. ladder: an entry, one stop for the whole size, at stop_loss or a
    /// trailing stop by trail, and the partial take_profit targets
    #[schemars(required)]
    pub(super) shape: Option<String>,
    /// oto and ladder: the entry's limit price; omitted, a market entry
    pub(super) entry_price: Option<f64>,
    /// oco: the limit leg's price; oto: the exit's limit price
    pub(super) limit_price: Option<f64>,
    /// oco: the stop leg's trigger; oto: the exit's stop trigger
    pub(super) stop_price: Option<f64>,
    /// oco only: make the stop leg a stop-limit at this limit
    pub(super) stop_limit_price: Option<f64>,
    /// oco only: both legs may only reduce an open position (an exit pair)
    pub(super) reduce_only: Option<bool>,
    /// ladder only: the stop-loss trigger, for the whole size
    pub(super) stop_loss: Option<f64>,
    /// the protective leg is a trailing stop instead (oco: in place of stop_price; oto: the exit; ladder: in place
    /// of stop_loss): the distance in price it keeps from the best price since it went live, with no activation and
    /// no limit
    pub(super) trail: Option<f64>,
    /// ladder only: the partial take-profits as price:qty,price:qty (one or more, summing to no more than qty)
    pub(super) take_profit: Option<String>,
    /// optional: every leg's id, as id,id,... one per leg in leg order (an oco's limit then its stop; an oto's entry
    /// then its exit; a ladder's entry, its stop, then its take-profits). Omitted, the server mints one per leg and
    /// the preview shows them. A resend under ids the node already holds is refused whole; a resend under minted
    /// ids is a new list
    pub(super) order_client_ids: Option<String>,
}

#[derive(Deserialize, JsonSchema)]
pub(super) struct SubmitComboArgs {
    #[schemars(required)]
    pub(super) venue: Option<String>,
    /// as submit_order's account: the combo is ONE order on this one account
    pub(super) account: Option<String>,
    /// 1 buys the combo / -1 sells it (every leg flips with it)
    #[schemars(required)]
    pub(super) side: Option<i64>,
    /// combo units: each leg trades |ratio| x qty of its own instrument
    #[schemars(required)]
    pub(super) qty: Option<f64>,
    /// two legs or more, in the venue's creation order, each an object {symbol, ratio, limit}: symbol the
    /// leg's instrument, ratio a non-zero integer, SIGNED (side x ratio above zero buys the leg), limit that
    /// leg's own limit price. Name a limit on every leg (a combo priced by its legs) or on none; any other
    /// key in a leg is refused
    // Each leg is read into [`ComboLegArgs`] on its own, so a refusal can name the leg.
    #[schemars(required)]
    pub(super) legs: Option<Vec<Value>>,
    /// the net limit per combo unit, SIGNED (the sum of ratio x price: a debit above zero, a credit below);
    /// omitted with no leg limit, a combo market order; never beside leg limits
    pub(super) net_limit: Option<f64>,
    /// optional: the combo's lifetime, submit_order's words: gtc (the default) | day | ioc | fok on a priced combo,
    /// or an auction, at_open | at_close; gtd (a combo carries no expiry) and post_only (no book models a maker-only
    /// combo) are refused; a book or a venue that cannot do it refuses the combo by name
    pub(super) time_in_force: Option<String>,
    /// optional: the combo's ONE order client id. Omitted, the server mints one and the preview shows it. A resend
    /// under an id the node already holds is refused whole; a resend under a minted id is a new combo
    pub(super) order_client_id: Option<String>,
}

/// One of `submit_combo`'s `legs`. Not advertised: the legs' schema is `submit_combo`'s description.
#[derive(Deserialize, JsonSchema)]
pub(super) struct ComboLegArgs {
    pub(super) symbol: Option<String>,
    pub(super) ratio: Option<i32>,
    pub(super) limit: Option<f64>,
}

