#[derive(Deserialize, JsonSchema)]
pub(super) struct MountStrategyArgs {
    /// an engine the node ALREADY runs — node_snapshot's venues[].venue, exactly (the comparison is
    /// case-sensitive)
    #[schemars(required)]
    pub(super) venue: Option<String>,
    /// WHICH ACCOUNT of `venue` this mount trades and reads — node_snapshot's venues[].account,
    /// exactly. OMIT it only where the node has ONE account of that venue, running or not: where it has two or more,
    /// an account-less mount is REFUSED rather than sent to the default one, because the default
    /// account's route key IS the bare venue and the silent answer would look correct. Pass "DEFAULT"
    /// to name the venue's unlabelled account deliberately — that is a DIFFERENT thing from omitting
    /// the field, and it is accepted at any account count
    pub(super) account: Option<String>,
    /// the mount's own symbol
    #[schemars(required)]
    pub(super) symbol: Option<String>,
    /// the mount's bar-series interval, e.g. `1m`
    #[schemars(required)]
    pub(super) interval: Option<String>,
    /// optional explicit mount id; omitting it derives `{venue}__{symbol}__{interval}`. Whatever this
    /// resolves to is what unmount_strategy will need
    pub(super) mount_id: Option<String>,
    /// the strategy FILE: its path under the NODE's strategies/ folder (a .rs or .rhai file, e.g.
    /// `trend/momentum.rs`). NOT script source, and not a path on this machine
    #[schemars(required)]
    pub(super) strategy: Option<String>,
    /// the [strategy.params] table; omitted means an empty table. Each strategy reads its own knobs,
    /// so this wire never re-declares them
    pub(super) params: Option<Map<String, Value>>,
}

#[derive(Deserialize, JsonSchema)]
pub(super) struct UnmountStrategyArgs {
    /// the mount id to remove — the explicit one given at mount time, or
    /// `{venue}__{symbol}__{interval}`
    #[schemars(required)]
    pub(super) mount_id: Option<String>,
}

#[derive(Deserialize, JsonSchema)]
// `value`'s `default` takes it out of `required`, which it is: the only way serde tells a `null` apart from absence.
#[schemars(extend("required" = ["key", "value"]))]
pub(super) struct SetSettingArgs {
    /// the FULL dotted key exactly as settings_show renders it (`config.tradehub_addr`,
    /// `policy.max_notional_per_order`); its first segment names the section
    #[schemars(required)]
    pub(super) key: Option<String>,
    /// the new value as TEXT — parsed as a TOML value (`250`, `true`, `["a"]`) when it is one, else
    /// written as a string, and then the row goes through the node's loader
    #[serde(default, deserialize_with = "as_given")]
    #[schemars(with = "String")]
    pub(super) value: Option<Value>,
}

#[derive(Deserialize, JsonSchema)]
pub(super) struct DeleteSeriesArgs {
    /// the EXACT stored kind (bar | quote | trade | book | depth | properties | …), never a substring
    #[schemars(required)]
    pub(super) kind: Option<String>,
    /// the EXACT venue slug, never a substring. ⚠ It names an EXCHANGE, never a data SOURCE — rows
    /// fetched from a metrics vendor land under the exchange they describe, which is why `produced_by`
    /// is the only thing that tells two producers of one series apart
    #[schemars(required)]
    pub(super) venue: Option<String>,
    /// the EXACT symbol of a PER-SYMBOL series. Omit to wildcard the dimension. Alternative to
    /// `group`, never a pair
    pub(super) symbol: Option<String>,
    /// the EXACT group of a GROUPED series (which holds many symbols in one part and has NO symbol of
    /// its own). Alternative to `symbol`
    pub(super) group: Option<String>,
    /// the EXACT bar interval (`1h`). Omit to wildcard; refused together with `group`, whose leaf has
    /// no interval segment
    pub(super) interval: Option<String>,
    /// REQUIRED. The commit-key PREFIX every key of every matched series must carry (`panel_bars:`,
    /// `pmxt:quote:`). ⚠ A LITERAL prefix, never a producer PATH: this tool deletes through a datahub,
    /// and a path is refused here before anything is dialled. `vike-cli data history rm --dry-run` reports
    /// each series' keys, or ask the operator — that is evidence from the store, where a path is a
    /// guess about a source tree you cannot see; and a datahub that has not been redeployed since
    /// 2026-09-11 resolves no path at all, so one sent there would be asserted literally, match no key,
    /// and report the store as foreign when in fact the argument was never resolved. One key that does
    /// not carry it refuses the whole run. There is no override and no --force.
    #[schemars(required)]
    pub(super) produced_by: Option<String>,
}
